use crate::dispatch::Key;
use std::collections::BTreeMap;
use std::ops::RangeInclusive;

#[derive(Clone)]
pub(super) enum Storage {
    Flat(Vec<(Key, usize)>),
    Tree(BTreeMap<Key, usize>),
}

impl Default for Storage {
    fn default() -> Self {
        Self::Flat(Vec::new())
    }
}

pub(super) enum Traversal<'storage> {
    Flat(std::slice::Iter<'storage, (Key, usize)>),
    Tree(std::collections::btree_map::Range<'storage, Key, usize>),
}

impl<'storage> Iterator for Traversal<'storage> {
    type Item = (&'storage Key, &'storage usize);

    fn next(&mut self) -> Option<Self::Item> {
        match self {
            Self::Flat(value) => value.next().map(|(key, position)| (key, position)),
            Self::Tree(value) => value.next(),
        }
    }
}

impl Storage {
    pub fn len(&self) -> usize {
        match self {
            Self::Flat(value) => value.len(),
            Self::Tree(value) => value.len(),
        }
    }

    pub fn get(&self, key: &Key) -> Option<&usize> {
        match self {
            Self::Flat(value) => value
                .binary_search_by_key(key, |(key, _)| *key)
                .ok()
                .map(|position| &value[position].1),
            Self::Tree(value) => value.get(key),
        }
    }

    pub fn insert(&mut self, key: Key, position: usize) -> bool {
        match self {
            Self::Tree(value) => value.insert(key, position).is_none(),
            Self::Flat(value) => match value.binary_search_by_key(&key, |(key, _)| *key) {
                Ok(index) => {
                    value[index].1 = position;
                    false
                }
                Err(index) => {
                    value.insert(index, (key, position));
                    if value.len() > 32 {
                        *self = Self::Tree(value.drain(..).collect());
                    }
                    true
                }
            },
        }
    }

    pub fn iter(&self) -> Traversal<'_> {
        match self {
            Self::Flat(value) => Traversal::Flat(value.iter()),
            Self::Tree(value) => Traversal::Tree(value.range(..)),
        }
    }

    pub fn range(&self, interval: RangeInclusive<Key>) -> Traversal<'_> {
        match self {
            Self::Flat(value) => {
                let start = value.partition_point(|(key, _)| key < interval.start());
                let end = value.partition_point(|(key, _)| key <= interval.end());
                Traversal::Flat(value[start..end].iter())
            }
            Self::Tree(value) => Traversal::Tree(value.range(interval)),
        }
    }

    pub fn extract<Predicate: FnMut(&Key, &mut usize) -> bool>(
        &mut self,
        interval: RangeInclusive<Key>,
        predicate: Predicate,
    ) -> Extraction<'_, Predicate> {
        match self {
            Self::Flat(value) => {
                let position = value.partition_point(|(key, _)| key < interval.start());
                let end = value.partition_point(|(key, _)| key <= interval.end());
                Extraction::Flat {
                    value,
                    position,
                    end,
                    predicate,
                }
            }
            Self::Tree(value) => Extraction::Tree(value.extract_if(interval, predicate)),
        }
    }
}

pub(super) enum Extraction<'storage, Predicate: FnMut(&Key, &mut usize) -> bool> {
    Flat {
        value: &'storage mut Vec<(Key, usize)>,
        position: usize,
        end: usize,
        predicate: Predicate,
    },
    Tree(
        std::collections::btree_map::ExtractIf<
            'storage,
            Key,
            usize,
            RangeInclusive<Key>,
            Predicate,
        >,
    ),
}

impl<Predicate: FnMut(&Key, &mut usize) -> bool> Iterator for Extraction<'_, Predicate> {
    type Item = (Key, usize);

    fn next(&mut self) -> Option<Self::Item> {
        match self {
            Self::Tree(value) => value.next(),
            Self::Flat {
                value,
                position,
                end,
                predicate,
            } => {
                while *position < *end {
                    let (key, item) = &mut value[*position];
                    if predicate(key, item) {
                        *end -= 1;
                        return Some(value.remove(*position));
                    }
                    *position += 1;
                }
                None
            }
        }
    }
}

